// Declarative structural contract for the offline eval suite.
//
// Each entry pins a source file to a required (or forbidden) substring. Lifting
// these out of runLocalEvals() means a future file rename/split edits ONE place
// instead of hundreds of scattered checkContains/checkFile call sites.
//
// Generated from the inline runLocalEvals() assertions; argument literals are
// preserved verbatim so behavior is identical.

export type StructureCheck =
  | { kind: "file"; path: string; name: string }
  | { kind: "contains"; path: string; needle: string; name: string }
  | { kind: "notContains"; path: string; needle: string; name: string };

const sf = (path: string, name: string): StructureCheck => ({ kind: "file", path, name });
const sc = (path: string, needle: string, name: string): StructureCheck => ({ kind: "contains", path, needle, name });
const snc = (path: string, needle: string, name: string): StructureCheck => ({ kind: "notContains", path, needle, name });

